import sys

def is_ambiguous(n, permutation):
    inverse_permutation = [0] * n
    for i in range(n):
        inverse_permutation[permutation[i] - 1] = i + 1
    return permutation == inverse_permutation

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    while True:
        n = int(data[index])
        if n == 0:
            break
        index += 1
        permutation = list(map(int, data[index:index + n]))
        index += n

        if is_ambiguous(n, permutation):
            print("ambiguous")
        else:
            print("not ambiguous")

